parameters.functionCode:
const newsItems = $input.all()[0].json.items;
const originalInput = $node['Parse Input'].json.original_input;

const keyword = originalInput.keyword || '네이버';
const count = originalInput.count || newsItems.length;

const decodeEntities = (text) =>
  text
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");

let html = `요청하신 <strong>"${keyword}"</strong> 관련 기사를 찾아 보내드립니다.<br/><br/>`;

if (!newsItems || newsItems.length === 0) {
  html += `<p><strong>"${keyword}"</strong>에 대한 뉴스를 찾을 수 없습니다.</p>`;
  return [{ json: { body: html, search_query: keyword, count: 0 } }];
}

newsItems.forEach((item, index) => {
  let title = decodeEntities(item.title.replace(/<[^>]+>/gm, ''));
  const description = decodeEntities(item.description.replace(/<[^>]+>/gm, ''));
  const link = item.link;

  // title이 짤려있다면 description의 앞부분으로 보정
  if (title.endsWith('…')) {
    const firstSentence = description.split(/[.!?]\s/)[0];
    if (firstSentence && firstSentence.length > title.length) {
      title = firstSentence;
    }
  }

  html += `<strong>${index + 1}. <a href="${link}" target="_blank">${title}</a></strong><br/>`;
  html += `요약내용 : ${description}<br/><br/>`;
});

return [{ json: { body: html, search_query: keyword, count: count } }];

// Parse Input 노드를 단순화
const input = $input.first().json;

console.log('=== Parse Input Debug ===');
console.log('Received from Code node:', JSON.stringify(input, null, 2));

// Code 노드에서 이미 파싱한 데이터를 그대로 사용
const keyword = input.keyword || "네이버";
const count = input.count || 1;

console.log('Using parsed values:', { keyword, count });

return [{
  json: {
    search_query: keyword,
    count: count,
    original_input: {
      keyword: keyword,
      count: count
    },
    full_text: `${keyword} 관련 뉴스 ${count}개`
  }
}];

parameters.jsCode:
const input = $input.first().json;

console.log('=== Code Node Input Debug ===');
console.log('Full input:', JSON.stringify(input, null, 2));

let keyword = "네이버";  // 기본값
let count = 1;           // 기본값

try {
  // 방법 1: 직접 구조로 전달된 경우
  if (input.query && input.query.input) {
    keyword = input.query.input;
    count = input.query.count || 1;
    console.log('Method 1 - Direct structure success');
  }

  // 방법 2: query가 문자열로 전달된 경우 (기존 로직)
  else if (typeof input.query === 'string') {
    const parsed = JSON.parse(input.query);
    keyword = parsed.query.input;
    count = parsed.query.count || 1;
    console.log('Method 2 - String parsing success');
  }

  // 방법 3: 전체 input 자체가 문자열인 경우
  else if (typeof input === 'string') {
    const parsed = JSON.parse(input);
    keyword = parsed.query.input;
    count = parsed.query.count || 1;
    console.log('Method 3 - Full input parsing success');
  }

  // 방법 4: input 필드에 직접 들어있는 경우  
  else if (input.input) {
    // 단순 문자열인 경우
    if (typeof input.input === 'string') {
      keyword = input.input;
      count = input.count || 1;
    }
    console.log('Method 4 - Input field success');
  }

} catch (error) {
  console.error('Parsing error:', error.message);
  console.log('Using default values');
}

// 최종 검증
if (!keyword || keyword.trim() === '') {
  keyword = "네이버";
}

if (!count || isNaN(count) || count < 1) {
  count = 1;
}

console.log('Final extracted values:', { keyword, count });

return {
  keyword,
  count,
  toolName: "Naver_News_Crawling",
  original: input
};
